package main

// Interface language: "en" (English) or "es" (Spanish).
var lang = "en"

// L returns the text in the selected language. Strings are written in English
// in the code; this table holds their Spanish translation.
func L(s string) string {
	if lang == "es" {
		if t, ok := es[s]; ok {
			return t
		}
	}
	return s
}

